      const usesOdooPack = (state.project.packs || []).some((pack) => pack.policies?.domain === "odoo" && pack.profiles.some((profile) => profiles.includes(profile.id)));
      if (g.domain !== "odoo" && !usesOdooPack) return "";
      const field = (name, label, placeholder) => `<label for="context-${name}">${label}</label><input id="context-${name}" name="context_${name}" value="${esc4(typeof p[name] === "string" ? p[name] : p[name] == null ? "" : JSON.stringify(p[name]))}" placeholder="${placeholder}">`;
      return `<fieldset class="workflow-context"><legend>Contexte Odoo</legend>${field("series", "Version d\u2019Odoo", "Exemple : 19.0")}${state.project.series ? `<small>Conversation : la version ${esc4(state.project.series)} du projet est prioritaire. Ce r\xE9glage sert aussi au mode automatique.</small>` : ""}<label for="context-platform">H\xE9bergement</label><select id="context-platform" name="context_platform">${contextOptions([["", "\xC0 pr\xE9ciser"], ["custom", "Odoo.sh ou serveur d\xE9di\xE9"], ["odoo.sh", "Odoo.sh"], ["online", "Odoo Online"], ["on-premise", "Serveur d\xE9di\xE9"]], p.platform || "")}</select>${state.project.platform ? `<small>Conversation : h\xE9bergement du projet ${esc4(state.project.platform)}.</small>` : ""}<label for="context-route">Type de r\xE9alisation</label><select id="context-route" name="context_route">${contextOptions([["", "\xC0 d\xE9terminer pendant l\u2019analyse"], ["module", "Module Odoo"], ["studio", "Odoo Studio"]], p.route || "")}</select><label for="context-environment">Environnement de recette</label><select id="context-environment" name="context_environment">${contextOptions([["", "\xC0 pr\xE9parer avec l\u2019agent"], ["local", "Copie locale neutralis\xE9e"], ["staging", "Staging (non admis pour cette recette)"], ["production", "Production (non admise pour les tests)"]], p.environment || "")}</select>${field("neutralized_copy", "R\xE9f\xE9rence de la copie de test", "Chemin ou identifiant de la copie pr\xE9par\xE9e")}<small>Ces informations seront n\xE9cessaires avant la recette. La copie doit \xEAtre r\xE9ellement pr\xE9par\xE9e et v\xE9rifi\xE9e ; remplir ces champs ne cr\xE9e pas de base de test.</small></fieldset>`;
